from round4_report import counts

def render(rows):
 from report import GATES
 lines=['# Issue #248 Phase B — Round 5','', '**PROVISIONAL on plateau Z24.65 / unmeasured Junana q=1.50. NOT RELEASED.**','', '## Round 5 results','', '| Gate | 17 mm | 16 mm |','|---|---|---|']
